export interface IEmailTransport {
  sendMail(message: { from: string; to: string; subject: string; html: string }): Promise<void>
}

export interface IEmailService {
  sendWelcomeEmail(to: string, name: string): Promise<void>
  sendPasswordReset(to: string, token: string): Promise<void>
}

import nodemailer from "nodemailer"
import { IEmailService, IEmailTransport } from "./interfaces"

export class EmailService implements IEmailService {
  private transporter: IEmailTransport

  constructor(transporter: IEmailTransport = nodemailer.createTransport({
    host: "smtp.gmail.com", port: 587,
    auth: { user: process.env.EMAIL_USER, pass: process.env.EMAIL_PASS }
  })) {
    this.transporter = transporter
  }

  async sendWelcomeEmail(to: string, name: string): Promise<void> {
    await this.transporter.sendMail({ from: "noreply@example.com", to, subject: "Welcome!", html: `<h1>Welcome, ${name}!</h1>` })
  }

  async sendPasswordReset(to: string, token: string): Promise<void> {
    await this.transporter.sendMail({ from: "noreply@example.com", to, subject: "Password Reset", html: `<p>Reset: https://example.com/reset?token=${token}</p>` })
  }
}

import { EmailService } from "./emailService"
import { IEmailService } from "./interfaces"

export class UserService {
  private emailService: IEmailService

  constructor(emailService: IEmailService = new EmailService()) {
    this.emailService = emailService
  }

  async registerUser(email: string, name: string) {
    const user = { id: String(Date.now()), email, name }
    await this.emailService.sendWelcomeEmail(email, name)
    return user
  }

  async requestPasswordReset(email: string): Promise<void> {
    const token = Math.random().toString(36).slice(2)
    await this.emailService.sendPasswordReset(email, token)
  }
}
